<?php
namespace App\Services;use App\Models\User;use Illuminate\Support\Facades\DB;
class StudentGamificationService {public function award(User $student):array{return DB::transaction(function()use($student){$student=User::query()->whereKey($student->id)->lockForUpdate()->firstOrFail();$student->increment('total_points');$student->increment('correct_answers');$student->refresh();$stars=intdiv($student->total_points,100);$activate=$student->total_points>=100&&!$student->is_premium;$updates=['total_stars'=>$stars];if($activate)$updates+=['is_premium'=>true,'premium_started_at'=>now(),'premium_expires_at'=>now()->addDays(10)];$student->update($updates);if($activate)DB::table('premium_job_campaigns')->updateOrInsert(['user_id'=>$student->id],['starts_at'=>today(),'ends_at'=>today()->addDays(10),'daily_recommendation_limit'=>10,'application_consent'=>false,'is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);return ['points'=>$student->total_points,'stars'=>$stars,'premium'=>$student->total_points>=100,'premium_activated'=>$activate];});}}
